const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = v => JSON.parse(JSON.stringify(v));
const fmt = (v,d=2) => v == null ? '—' : Number(v).toLocaleString('en-US',{maximumFractionDigits:d});
const compact = v => v==null?'—':v>=1e9?(v/1e9).toFixed(2)+'G':v>=1e6?(v/1e6).toFixed(2)+'M':v>=1e3?(v/1e3).toFixed(1)+'K':fmt(v);
const pct = v => v==null?'—':(v*100).toFixed(1)+'%';
const clockTime = t => new Date(t*1000).toLocaleTimeString('en-US',{hour12:false});
