const icon = n => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[n]||ICONS.layers}"/></svg>`;
function hydrate(){ $$('i[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon)); }
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),error?9000:4500);}
async function api(path,method='GET',body){const opts={method};if(body instanceof FormData)opts.body=body;else if(body!==undefined){opts.headers={'Content-Type':'application/json'};opts.body=JSON.stringify(body);}const r=await fetch('/api'+path,opts);if(!r.ok){let x;try{x=await r.json()}catch{x={detail:r.statusText}}throw Error(typeof x.detail==='string'?x.detail:JSON.stringify(x.detail));}return r.json();}
function fire(fn){return async(...args)=>{try{await fn(...args)}catch(e){toast(e.message,true);console.error(e)}}}
const titles={architecture:'Architecture Studio',datasets:'Dataset Studio',search:'Search Lab',training:'Training Studio',experiments:'Experiment Lab',settings:'Runtime & Capabilities'};
const S={projects:[],datasets:[],jobs:[],system:{},project:null,ir:null,analysis:null,page:'architecture',selected:null,dirty:false,history:[],future:[],positions:{},zoom:.8,pan:{x:80,y:24},connecting:null,logs:[],view:'graph',searchJob:null,trainJob:null,dataset:null,candidate:null,compare:[],consoleTab:'checks'};
function setDirty(){S.dirty=true;$('#save-state').innerHTML='<span class="status-dot" style="background:var(--orange)"></span> Unsaved';}
function saved(){S.dirty=false;$('#save-state').innerHTML='<span class="status-dot"></span> Saved · v'+S.project.revision;}
function history(){S.history.push(clone(S.ir));if(S.history.length>50)S.history.shift();S.future=[];}
function log(text,kind='ok'){S.logs.push({text,kind,time:Date.now()/1000});if(S.logs.length>100)S.logs.shift();renderConsole();}
function modal(title,body,footer=''){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-close>${icon('x')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-actions">${footer}</div>`:''}`;$$('[data-close]',$('#modal')).forEach(b=>b.onclick=()=>$('#modal').close());if(!$('#modal').open)$('#modal').showModal();hydrate();}
const btn = (text,action,ico='',primary=false) => `<button class="btn ${primary?'primary':''}" data-action="${action}">${ico?icon(ico):''}${text}</button>`;
const empty = (title,text,action='') => `<div class="empty-state">${icon('orbit')}<h3>${title}</h3><p>${text}</p>${action}</div>`;
const field=(label,name,value,type='number',attrs='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
function heading(k,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function metric(label,value,unit,note,ico='chip'){return `<div class="metric"><div class="metric-label">${label}${icon(ico)}</div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-note">${note}</div></div>`;}
function badge(status){const names={queued:'Queued',running:'Running',pausing:'Pausing',cancelling:'Cancelling',completed:'Completed',failed:'Failed',paused:'Paused',cancelled:'Cancelled',interrupted:'Interrupted'};return `<span class="badge ${status==='completed'?'green':['running','queued'].includes(status)?'purple':['failed','interrupted'].includes(status)?'orange':''}">${esc(names[status]||status)}</span>`;}
function dataset(){return S.datasets.find(d=>d.id===(S.dataset||S.project?.dataset_id))||S.datasets[0];}
async function analyze(show=true){try{S.analysis=await api('/analyze','POST',{ir:S.ir});if(show)log(`Structure valid · ${S.analysis.nodes.length} operators · ${S.analysis.params.toLocaleString()} parameters`);return true}catch(e){S.analysis=null;log(e.message,'warn');if(show)toast(e.message,true);return false}}
async function loadProject(p){S.project=p;S.ir=clone(p.ir);S.dataset=p.dataset_id;S.selected=S.ir.nodes[0]?.id;S.history=[];S.future=[];S.positions=clone(p.layout||{});S.logs=[];S.candidate=null;S.zoom=.8;S.pan={x:75,y:25};saved();$('#project-name').textContent=p.name;await analyze(false);navigate(S.page);}
async function save(){const p=await api('/projects/'+S.project.id,'PUT',{name:S.project.name,ir:S.ir,dataset_id:S.project.dataset_id,layout:S.positions});S.project=p;S.projects=S.projects.map(x=>x.id===p.id?p:x);saved();if($('.canvas-hint'))$('.canvas-hint').textContent=(S.ir.name||'ForgeNet')+' / v'+p.revision+' · '+S.ir.input_shape.join(' × ');toast('Project and architecture version saved');}
function navigate(page){S.page=page;$('#page-title').textContent=titles[page];document.title=`NeuroForge AI · ${titles[page]}`;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#footer-context').textContent=page==='architecture'?'Architecture canvas':'Local workspace · '+titles[page];render();}
function render(){if(!S.project)return;({architecture:renderArchitecture,datasets:renderDatasets,search:renderSearch,training:renderTraining,experiments:renderExperiments,settings:renderSettings,modules:renderModules,exports:renderExportStudio}[S.page])();hydrate();bindActions();}
const opSymbols={Conv2d:'⊞',ResidualBlock:'↗',BatchNorm2d:'μ',ReLU:'⌁',MaxPool2d:'↓',AvgPool2d:'↓',AdaptiveAvgPool2d:'⊡',Flatten:'≡',Linear:'↦',Dropout:'%',Add:'+',Concat:'⋈',Input:'↳'};
function opIcon(op){return `<span class="op-icon" ${op==='ResidualBlock'?'style="color:var(--purple);border-color:#bba5ef35;background:#bba5ef10"':''}>${opSymbols[op]||'◇'}</span>`;}
function renderArchitecture(){const a=S.analysis;$('#page').innerHTML=heading('DESIGN / 01','Architecture Studio','From an idea to an executable neural network.',btn('Export','export-project','download')+btn('Validate graph','validate','check')+btn('Proxy Analysis','proxy','orbit',true))+`<div class="metrics-strip">${metric('TOTAL PARAMETERS',a?compact(a.params):'—','','Trainable parameters · FP32','layers')}${metric('COMPUTATIONAL COST',a?compact(a.macs):'—','MACs','Conv / Linear · Per sample','activity')}${metric('PARAMETER MEMORY',a?fmt(a.parameter_memory_mb):'—','MB','','chip')}${metric('STRUCTURE STATUS',a?'<span class="good">● VALID GRAPH</span>':'<span class="danger" style="font-size:12px">CHECK REQUIRED</span>','',a?`${a.nodes.length} operators · Tensor shapes consistent`:'Validate after editing','check')}</div>
<div class="editor-shell"><div class="editor-toolbar"><div class="tabs"><button class="tab ${S.view==='graph'?'active':''}" data-action="graph-view">${icon('graph')}Model Graph</button><button class="tab ${S.view==='code'?'active':''}" data-action="code-view">${icon('code')}PyTorch</button></div><div class="actions"><span class="mode-tag">MODEL VIEW</span><span class="toolbar-divider"></span><button class="icon-button" data-action="undo" title="Undo Ctrl+Z" ${!S.history.length?'disabled':''}>${icon('undo')}</button><button class="icon-button" data-action="redo" title="Redo Ctrl+Y" ${!S.future.length?'disabled':''}>${icon('redo')}</button><button class="icon-button" data-action="save" title="Save Ctrl+S">${icon('save')}</button><span class="toolbar-divider"></span><button class="icon-button" data-action="import-ir" title="Import architecture JSON">${icon('upload')}</button><button class="icon-button" data-action="template" title="New network template">${icon('plus')}</button></div></div>
<div class="editor-body"><aside class="library" ${S.view==='code'?'style="display:none"':''}><div class="section-title">COMPONENTS <span>${S.system.ops?.length||13}</span></div><div class="search-input"><i>${icon('search')}</i><input id="component-search" placeholder="Search components…" aria-label="Search components"></div><div id="components">${renderComponents()}</div><div class="library-tip">Click to add after the selected node.<br>Drag a component onto the canvas.<br>Connect an output port to an input port.</div></aside><div class="canvas" id="canvas" ${S.view==='code'?'style="display:none"':''}><div class="canvas-hint">${esc(S.ir.name||'ForgeNet')} / v${S.project.revision} <span style="color:#414d47"> · </span> ${esc(S.ir.input_shape.join(' × '))}</div><div class="canvas-viewport" id="viewport"><svg class="connections" id="connections"></svg><div id="nodes"></div></div><div class="canvas-controls"><button class="icon-button" data-action="zoom-out" title="Zoom out">${icon('minus')}</button><span class="zoom-label" id="zoom-label">80%</span><button class="icon-button" data-action="zoom-in" title="Zoom in">${icon('plus')}</button><span class="toolbar-divider"></span><button class="icon-button" data-action="fit" title="Fit canvas">${icon('fit')}</button><button class="icon-button" data-action="layout" title="Auto layout">${icon('layout')}</button></div><div class="canvas-caption">Scroll to zoom · Drag background to pan<br>Drag nodes · Delete to remove</div></div><aside class="inspector" id="inspector" ${S.view==='code'?'style="display:none"':''}></aside><div class="code-panel" id="code-panel" ${S.view==='code'?'style="display:block"':''}><button class="btn small code-copy" data-action="download-code">${icon('download')}Download model.py</button><pre id="source-code">Generating…</pre></div></div><div class="console"><div class="console-head"><div class="tabs"><button class="tab ${S.consoleTab==='checks'?'active':''}" data-console="checks">${icon('check')}Analysis Console</button><button class="tab ${S.consoleTab==='proxy'?'active':''}" data-console="proxy">${icon('orbit')}Proxy Results</button></div><span class="badge green" style="padding:2px 5px;font-size:7px">PYTORCH CONNECTED</span></div><div class="console-lines" id="console-lines"></div></div></div><p class="note-footer" style="margin:12px 27px">Neural Architecture IR v1 · Deterministic shape checking and PyTorch compilation · Local execution</p>`;
if(S.view==='graph'){layoutMissing();renderGraph();renderInspector();bindCanvas();}else loadCode();renderConsole();$('#component-search')?.addEventListener('input',e=>{$$('.component').forEach(b=>b.hidden=!b.dataset.op.toLowerCase().includes(e.target.value.toLowerCase()))});$$('[data-console]').forEach(b=>b.onclick=()=>{S.consoleTab=b.dataset.console;renderArchitecture();bindActions()});$$('.component[data-op]').forEach(b=>{b.onclick=fire(()=>addNode(b.dataset.op));b.ondragstart=e=>e.dataTransfer.setData('application/neuroforge',b.dataset.op);});}
function renderComponents(){return [['LAYERS',['Conv2d','Linear','ResidualBlock']],['TRANSFORMS',['ReLU','BatchNorm2d','MaxPool2d','AvgPool2d','AdaptiveAvgPool2d','Flatten','Dropout']],['CONNECTIONS',['Add','Concat']]].map(([g,ops])=>`<div class="library-group">${g}</div>${ops.map(op=>`<button class="component" data-op="${op}" draggable="true">${opIcon(op)}<span>${op}</span><span class="add-mark">+</span></button>`).join('')}`).join('');}
function layoutMissing(){const ids=['input',...S.ir.nodes.map(n=>n.id)];ids.forEach((id,i)=>{if(!S.positions[id])S.positions[id]={x:45+Math.floor(i/4)*245,y:25+(i%4)*110};});}
function renderGraph(){const nodes=[{id:'input',op:'Input',inputs:[],config:{}},...S.ir.nodes];$('#nodes').innerHTML=nodes.map(n=>{const spec=S.analysis?.nodes.find(x=>x.id===n.id);const shape=n.id==='input'?S.ir.input_shape:spec?.shape;const pos=S.positions[n.id];return `<div class="node ${S.selected===n.id?'selected':''} ${n.id==='input'?'input-node':''}" data-node="${esc(n.id)}" style="left:${pos.x}px;top:${pos.y}px">${n.id!=='input'?`<button class="port in" data-port="in" title="Connect input" aria-label="${esc(n.id)} Input port"></button>`:''}<div class="node-head">${opIcon(n.op)}<div><div class="node-title">${esc(n.op)}</div><div class="node-id">${esc(n.id)}</div></div>${n.id===S.ir.output?'<span class="node-badge">OUT</span>':''}</div><div class="node-meta"><span class="node-shape">${shape?shape.join(' × '):'check required'}</span><span>${spec?compact(spec.params):'tensor'}</span></div><button class="port out ${S.connecting===n.id?'connecting':''}" data-port="out" title="Connect output" aria-label="${esc(n.id)} Output port"></button></div>`}).join('');renderWires();applyTransform();$$('[data-node]').forEach(el=>{el.onpointerdown=e=>{if(e.target.closest('[data-port]'))return;e.stopPropagation();S.selected=el.dataset.node;$$('[data-node]').forEach(n=>n.classList.toggle('selected',n===el));renderInspector();const p=S.positions[S.selected],start={x:e.clientX,y:e.clientY},orig={...p};el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{p.x=Math.max(0,orig.x+(ev.clientX-start.x)/S.zoom);p.y=Math.max(0,orig.y+(ev.clientY-start.y)/S.zoom);el.style.left=p.x+'px';el.style.top=p.y+'px';renderWires()};el.onpointerup=()=>{el.onpointermove=null;if(p.x!==orig.x||p.y!==orig.y)setDirty()};};$$('[data-port]',el).forEach(port=>{port.onpointerdown=e=>e.stopPropagation();port.onclick=fire(async e=>{e.stopPropagation();if(port.dataset.port==='out'){S.connecting=S.connecting===el.dataset.node?null:el.dataset.node;renderGraph();return;}if(!S.connecting)return;const node=S.ir.nodes.find(n=>n.id===el.dataset.node);if(S.connecting===node.id)throw Error('A node cannot connect to itself');history();if(['Add','Concat'].includes(node.op)){if(!node.inputs.includes(S.connecting))node.inputs.push(S.connecting)}else node.inputs=[S.connecting];S.connecting=null;setDirty();await analyze(false);renderArchitecture();bindActions()})});});}
function renderWires(){if(!$('#connections'))return;$('#connections').innerHTML=S.ir.nodes.flatMap(n=>n.inputs.map(id=>{const a=S.positions[id],b=S.positions[n.id];if(!a||!b)return '';const x=a.x+85,y=a.y+83,x2=b.x+85,y2=b.y;const mid=(y+y2)/2;return `<path class="wire" d="M${x} ${y} C${x} ${mid},${x2} ${mid},${x2} ${y2}"/>`})).join('');}
function applyTransform(){if(!$('#viewport'))return;const surface=$('#canvas');if(surface){surface.scrollTop=0;surface.scrollLeft=0;}$('#viewport').style.transform=`translate(${S.pan.x}px,${S.pan.y}px) scale(${S.zoom})`;$('#zoom-label').textContent=Math.round(S.zoom*100)+'%';}
function bindCanvas(){const c=$('#canvas');c.onwheel=e=>{e.preventDefault();const box=c.getBoundingClientRect(),x=e.clientX-box.left,y=e.clientY-box.top,old=S.zoom;S.zoom=Math.min(1.5,Math.max(.2,S.zoom*(e.deltaY>0?.9:1.1)));S.pan.x=x-(x-S.pan.x)*S.zoom/old;S.pan.y=y-(y-S.pan.y)*S.zoom/old;applyTransform()};c.onpointerdown=e=>{if(e.target.closest('.node,.canvas-controls,.selection-toolbar'))return;const start={x:e.clientX,y:e.clientY},orig={...S.pan};c.setPointerCapture(e.pointerId);c.onpointermove=ev=>{S.pan.x=orig.x+ev.clientX-start.x;S.pan.y=orig.y+ev.clientY-start.y;applyTransform()};c.onpointerup=()=>c.onpointermove=null};c.ondragover=e=>e.preventDefault();c.ondrop=fire(async e=>{e.preventDefault();const op=e.dataTransfer.getData('application/neuroforge');if(!op)return;const box=c.getBoundingClientRect();await addNode(op,{x:(e.clientX-box.left-S.pan.x)/S.zoom,y:(e.clientY-box.top-S.pan.y)/S.zoom})});}
function renderInspector(){if(!$('#inspector'))return;const n=S.ir.nodes.find(n=>n.id===S.selected);const spec=S.analysis?.nodes.find(n=>n.id===S.selected);if(!n){$('#inspector').innerHTML=`<div class="section-title">INSPECTOR ${icon('settings')}</div><div class="inspector-heading">${opIcon('Input')}<div><h3>Input Tensor</h3><p>input · NCHW</p></div></div><div class="inspector-kv"><span>Shape</span><code>${S.ir.input_shape.join(' × ')}</code></div><div class="info-box">Input dimensions come from the selected dataset version. Apply a dataset to update the model.</div><div class="section-title" style="margin-top:25px">MODEL INFORMATION</div><div class="inspector-kv"><span>IR Schema</span><code>v1</code></div><div class="inspector-kv"><span>Output</span><code>${esc(S.ir.output)}</code></div><div class="inspector-kv"><span>Graph hash</span><code>${S.analysis?.hash.slice(0,10)||'—'}</code></div>`;return;}
$('#inspector').innerHTML=`<div class="section-title">INSPECTOR ${icon('settings')}</div><div class="inspector-heading">${opIcon(n.op)}<div><h3>${esc(n.op)}</h3><p>${esc(n.id)} · operator</p></div></div><form id="node-form">${Object.entries(n.config).map(([k,v])=>field(k,k,v,'number',`step="${k==='p'?'0.05':'1'}"`)).join('')}${n.op==='AdaptiveAvgPool2d'?'<div class="field-note">Global average pooling → C × 1 × 1</div>':''}<label class="field"><span>Input nodes (comma-separated)</span><input name="_inputs" value="${esc(n.inputs.join(', '))}"></label><button class="btn small full-width" type="submit">${icon('check')}Apply parameters</button></form><div class="section-title" style="margin-top:23px">TENSOR & COMPUTE</div><div class="inspector-kv"><span>Input shape</span><code>${spec?.input_shapes.map(s=>s.join('×')).join(', ')||'—'}</code></div><div class="inspector-kv"><span>Output shape</span><code>${spec?.shape.join('×')||'—'}</code></div><div class="inspector-kv"><span>Parameters</span><code>${spec?fmt(spec.params):'—'}</code></div><div class="inspector-kv"><span>MACs</span><code>${spec?compact(spec.macs):'—'}</code></div><div class="info-box ${spec?'':'warning'}">${spec?'Tensor checks passed. Parameter edits recompile the graph and preserve architecture history.':'Graph validation failed. Check Analysis Console and fix connections or parameters.'}</div><div class="actions">${btn('Set as output','set-output','arrow')}${btn('Delete','delete-node','trash')}</div>`;$('#node-form').onsubmit=fire(async e=>{e.preventDefault();const form=new FormData(e.currentTarget);history();for(const key of Object.keys(n.config)){n.config[key]=Number(form.get(key))}n.inputs=String(form.get('_inputs')).split(',').map(v=>v.trim()).filter(Boolean);setDirty();await analyze(false);renderArchitecture();bindActions()});$$('[data-action]',$('#inspector')).forEach(bindAction);}
async function addNode(op,pos){history();const after=S.selected||'input';let id=op.toLowerCase(),i=1;while(S.ir.nodes.some(n=>n.id===id+i))i++;id+=i;const defaults={Conv2d:{out_channels:16,kernel_size:3,stride:1,padding:1},ResidualBlock:{out_channels:16,kernel_size:3,stride:1,padding:1},MaxPool2d:{kernel_size:2},AvgPool2d:{kernel_size:2},Linear:{out_features:dataset()?.classes.length||3},Dropout:{p:.2}};
const n={id,op,inputs:[after],config:defaults[op]||{}};S.ir.nodes.forEach(x=>{x.inputs=x.inputs.map(v=>v===after?id:v)});if(S.ir.output===after)S.ir.output=id;const idx=S.ir.nodes.findIndex(x=>x.id===after);S.ir.nodes.splice(idx+1,0,n);S.selected=id;if(pos)S.positions[id]=pos;else S.positions={};setDirty();await analyze(false);renderArchitecture();bindActions();}
async function deleteNode(){const n=S.ir.nodes.find(n=>n.id===S.selected);if(!n)return;history();S.ir.nodes=S.ir.nodes.filter(x=>x!==n);S.ir.nodes.forEach(x=>x.inputs=[...new Set(x.inputs.flatMap(i=>i===n.id?n.inputs:[i]))]);if(S.ir.output===n.id)S.ir.output=n.inputs[0]||S.ir.nodes.at(-1)?.id;delete S.positions[n.id];S.selected=n.inputs[0];setDirty();await analyze(false);renderArchitecture();bindActions();}
async function loadCode(){try{const r=await api('/code','POST',{ir:S.ir});if($('#source-code'))$('#source-code').textContent=r.code}catch(e){if($('#source-code'))$('#source-code').textContent=e.message}}
function renderConsole(){const el=$('#console-lines');if(!el)return;if(S.consoleTab==='proxy'){const job=S.jobs.find(j=>j.kind==='proxy'&&j.payload.project_id===S.project.id);if(!job){el.innerHTML='<span class="muted">No proxy analysis yet. Run Proxy Analysis to measure the current network.</span>';return;}const c=job.candidates?.[0];el.textContent=c?`SynFlow: ${fmt(c.proxy.scores.synflow,6)}    SNIP: ${fmt(c.proxy.scores.snip,6)}    NASWOT: ${fmt(c.proxy.scores.naswot,6)}\nCPU elapsed: ${fmt(c.proxy.seconds,3)}s · Seed: ${c.proxy.seed} · Batch: ${c.proxy.batch_size}\nUncalibrated signals. Does not represent predicted accuracy.`:job.status+(job.error?' · '+job.error:' · Computing…');return;}if(!S.logs.length){log('NeuroForge compiler ready · Local PyTorch runtime connected');if(S.analysis)log(`Graph compiled · ${S.analysis.nodes.length} operators · output [N, ${S.analysis.output_shape.join(', ')}]`);return;}el.innerHTML=S.logs.map(l=>`<div class="logline"><time>${clockTime(l.time)}</time><span class="${l.kind}">${l.kind==='warn'?'!':'✓'} ${esc(l.text)}</span></div>`).join('');el.scrollTop=el.scrollHeight;}

function renderDatasets(){const d=dataset();$('#page').innerHTML=heading('DATA / 02','Dataset Studio','Make your data a traceable engineering asset.',btn('Import image dataset','upload-dataset','upload',true))+`<div class="page-content"><div class="split-layout"><div class="stack"><div class="panel"><div class="panel-header"><h2>Dataset Overview</h2><select id="dataset-select" class="inline-select">${S.datasets.map(x=>`<option value="${x.id}" ${x.id===d?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${d?`<div class="panel-body"><div class="stat-inline"><div><small>SAMPLES</small><strong>${fmt(d.samples)}</strong></div><div><small>CLASSES</small><strong>${d.classes.length}</strong></div><div><small>INPUT SHAPE</small><strong style="font-size:19px">${d.shape.join(' × ')}</strong></div><div><small>DUPLICATES</small><strong>${d.duplicates}</strong></div></div><div class="section-title" style="margin-top:26px">SAMPLE PREVIEW <span>RGB / ${d.shape[1]}PX</span></div><div class="dataset-grid">${Array.from({length:Math.min(16,d.samples)},(_,i)=>`<img class="dataset-image" src="/api/datasets/${d.id}/preview/${i* Math.max(1,Math.floor(d.samples/16))}" alt="Dataset sample ${i+1}">`).join('')}</div><div class="info-box ${d.issues.length?'warning':''}">${d.source.startsWith('synthetic')?'Built-in synthetic shapes verify the workflow; they do not measure real-world vision performance.':'Decoded as RGB images and resized consistently. Original files remain unchanged.'} ${d.issues.length?`${d.issues.length}  files failed to decode. See the quality report.`:''}</div></div>`:empty('Import your first dataset','Upload a class_name/image.png  ZIP archive.')}</div><div class="panel"><div class="panel-header"><h2>Class Distribution</h2><span class="badge ${d?.imbalance_ratio>2?'orange':'green'}">${d?.imbalance_ratio>2?'Class imbalance detected':'Class distribution'} · ${fmt(d?.imbalance_ratio)}×</span></div><div class="panel-body">${d?.classes.map((c,i)=>`<div class="class-row"><span title="${esc(c)}">${esc(c)}</span><div class="bar"><span style="width:${d.counts[i]/Math.max(...d.counts)*100}%"></span></div><code>${d.counts[i]}</code></div>`).join('')||''}</div></div></div><aside class="stack"><div class="panel"><div class="panel-header"><h2>Dataset Version</h2>${icon('database')}</div><div class="panel-body"><span class="badge purple">CONTENT ADDRESSED</span><p class="settings-code" style="font-size:10px">${d?.id.slice(0,24)||'—'}…</p><div class="inspector-kv"><span>Seed</span><code>${d?.seed}</code></div><div class="inspector-kv"><span>Split method</span><code>stratified / grouped</code></div><div class="inspector-kv"><span>Parent version</span><code>${d?.parent?.slice(0,8)||'initial'}</code></div><div class="info-box">Duplicate pixels stay in the same group. Train, validation and test indices are saved with the version.</div>${btn('Apply to current model','apply-dataset','check',true)}<p class="field-note">Updates input dimensions and the final Linear classifier.</p></div></div><div class="panel"><div class="panel-header"><h2>Data Split</h2><button class="link-button" data-action="resplit">Re-split dataset</button></div><div class="panel-body"><div class="segmented-bar">${['train','val','test'].map((k,i)=>`<span style="width:${d?d.split_counts[k]/d.samples*100:0}%;background:${['var(--accent)','var(--blue)','var(--purple)'][i]}"></span>`).join('')}</div><div class="legend">${['train','val','test'].map((k,i)=>`<span><b style="background:${['var(--accent)','var(--blue)','var(--purple)'][i]}"></b>${k} ${d?.split_counts[k]}</span>`).join('')}</div></div></div><div class="panel"><div class="panel-header"><h2>Processing Pipeline</h2></div><div class="panel-body">${d?.pipeline.map((p,i)=>`<div class="diff-row"><span class="accent">0${i+1}</span> ${esc(p.op)}<small class="muted" style="display:block">${esc(JSON.stringify(p))}</small></div>`).join('')||''}<button class="link-button section-gap" data-action="quality-report">View data quality and version manifest →</button></div></div></aside></div></div>`;$('#dataset-select').onchange=e=>{S.dataset=e.target.value;render()};}
function projectJobs(kind){return S.jobs.filter(j=>j.payload.project_id===S.project.id&&(!kind||j.kind===kind));}
function currentSearch(){return S.jobs.find(j=>j.id===S.searchJob)||projectJobs('search')[0];}
function currentTrain(){return S.jobs.find(j=>j.id===S.trainJob)||projectJobs('train')[0];}
function chips(name,values,checked){return `<div class="select-chips">${values.map(v=>`<label class="chip"><input type="checkbox" name="${name}" value="${v}" ${checked.includes(v)?'checked':''}>${v===true?'Residual':v===false?'Conv + ReLU':v}</label>`).join('')}</div>`;}
function renderSearch(){if($('#search-form'))S.searchConfig=[...new FormData($('#search-form'))];const j=currentSearch(),cs=j?.candidates||[],chosen=cs.find(c=>c.id===S.candidate)||cs[0];$('#page').innerHTML=heading('EXPLORE / 03','Search Lab','Explore architecture before allocating training resources.',btn('Compare candidates','compare-candidates','compare')+btn('Train selected candidate','train-candidate','play',true))+`<div class="page-content"><div class="split-layout"><div class="stack"><div class="panel"><div class="panel-header"><h2>Pareto Explorer <small>Combined proxy ranking × Model size</small></h2><span class="badge purple">UNCALIBRATED</span></div><div class="panel-body">${cs.length?scatter(cs,chosen?.id):empty('Explore your next network','Run a search to inspect real proxy signals, candidate ranks and the Pareto frontier.')}<div class="legend"><span><b></b>Pareto frontier</span><span><b style="background:var(--muted)"></b>Candidate</span><span style="margin-left:auto">Click a point to select an architecture</span></div></div></div><div class="panel"><div class="panel-header"><h2>Candidate Explorer <small>${cs.length} candidates</small></h2>${j?badge(j.status):'<span class="muted">Waiting for search</span>'}</div>${j?`<div class="panel-body" style="padding-bottom:0">${jobProgress(j)}</div>`:''}<div class="table-scroll">${cs.length?candidateTable(cs,chosen?.id):empty('Candidates will appear here','Random Search  and Evolutionary Search both perform real structure validation and proxy computation.')}</div></div>${chosen?candidateDetail(chosen,j):''}</div><aside class="stack"><div class="panel"><div class="panel-header"><h2>Search Space</h2>${icon('settings')}</div><form class="panel-body" id="search-form"><label class="field"><span>Search strategy</span><select name="strategy"><option value="random">Random Search · Baseline</option><option value="evolution">Evolutionary Search · Mutation</option></select></label><div class="form-label">Channel width</div>${chips('channels',[4,8,16,24,32,48,64],[8,16,24,32])}<div class="form-label">Block depth</div>${chips('depth',[1,2,3,4],[1,2,3])}<div class="form-label">Block family</div>${chips('residual',[true,false],[true,false])}<div class="form-grid">${field('Candidate budget','count',12,'number','min="2" max="64"')}${field('Random seed','seed',42,'number','min="0"')}${field('Parameter limit (M)','params',1,'number','min="0.001" max="20" step="any"')}${field('MACs Limit (M)','macs',100,'number','min="0.001" max="2000" step="any"')}</div><div class="info-box">Supported scope: current image classification dataset + CNN / Residual  template space. Search creates candidates without changing the draft.</div><button class="btn primary full-width" type="submit">${icon('orbit')}Start architecture search</button></form></div><div class="panel"><div class="panel-header"><h2>Proxy Protocol</h2></div><div class="panel-body"><span class="badge green">SynFlow</span> <span class="badge green">SNIP</span> <span class="badge green">NASWOT</span><p class="field-note">Fixed seeds and the same training subset batch. Methods initialize independently without weight updates. Available nonconstant signals use equal-weight percentile ranks.</p><div class="info-box warning">Proxy rank is not final accuracy. Calibrated performance intervals are unavailable; validate several candidates with short training.</div></div></div>${projectJobs('search').length?`<div class="panel"><div class="panel-header"><h2>Search History</h2></div>${projectJobs('search').slice(0,8).map(x=>`<button class="job-card full-width ${x.id===j?.id?'active':''}" data-search-job="${x.id}"><div><strong>${esc(x.payload.strategy)} · ${x.candidates.length} candidates</strong><small>${clockTime(x.created_at)} · ${x.id.slice(0,8)}</small></div>${badge(x.status)}</button>`).join('')}</div>`:''}</aside></div></div>`;
if(S.searchConfig){for(const el of $('#search-form').elements){if(el.type==='checkbox')el.checked=S.searchConfig.some(([k,v])=>k===el.name&&v===el.value);else if(el.name){const entry=S.searchConfig.find(([k])=>k===el.name);if(entry)el.value=entry[1];}}}$('#search-form').onsubmit=fire(async e=>{e.preventDefault();const f=new FormData(e.currentTarget),p={strategy:f.get('strategy'),count:Number(f.get('count')),seed:Number(f.get('seed')),max_params:Math.round(Number(f.get('params'))*1e6),max_macs:Math.round(Number(f.get('macs'))*1e6),channels:f.getAll('channels').map(Number),depth:f.getAll('depth').map(Number),residual:f.getAll('residual').map(v=>v==='true')};if(!p.channels.length||!p.depth.length||!p.residual.length)throw Error('Choose at least one value for each search variable');const job=await startTask('search',p);S.searchJob=job.id;S.candidate=null;render()});bindCandidateEvents(cs);$$('[data-search-job]').forEach(b=>b.onclick=()=>{S.searchJob=b.dataset.searchJob;S.candidate=null;render()});}
function scatter(cs,chosen){const w=640,h=255,left=54,right=22,top=18,bottom=43,maxP=Math.max(...cs.map(c=>c.proxy.params))*1.12;const x=c=>left+c.proxy.params/maxP*(w-left-right),y=c=>top+(1-c.score)*(h-top-bottom);return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Parameter count versus proxy percentile rank">${[0,.25,.5,.75,1].map(v=>`<line class="gridline" x1="${left}" y1="${top+(1-v)*(h-top-bottom)}" x2="${w-right}" y2="${top+(1-v)*(h-top-bottom)}"/><text x="${left-9}" y="${top+(1-v)*(h-top-bottom)+3}" text-anchor="end">${v.toFixed(2)}</text>`).join('')}${[0,.25,.5,.75,1].map(v=>`<text x="${left+v*(w-left-right)}" y="${h-bottom+18}" text-anchor="middle">${compact(maxP*v)}</text>`).join('')}<text x="${w/2}" y="${h-5}" text-anchor="middle">PARAMETERS →</text><text x="14" y="${h/2}" transform="rotate(-90 14 ${h/2})" text-anchor="middle">PROXY PERCENTILE →</text>${cs.map(c=>`<circle data-candidate="${c.id}" cx="${x(c)}" cy="${y(c)}" r="${c.id===chosen?7:4.5}" fill="${c.pareto?'var(--accent)':'var(--muted)'}" stroke="${c.id===chosen?'var(--text)':'transparent'}" stroke-width="1.5"><title>${c.id} · ${compact(c.proxy.params)} params · proxy ${c.score.toFixed(3)}</title></circle>`).join('')}</svg>`;}
function candidateTable(cs,chosen){return `<table><thead><tr><th></th><th>Rank / Architecture</th><th>Proxy score</th><th>Params</th><th>MACs</th><th>Disagreement</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr class="${c.id===chosen?'selected-row':''}"><td><input type="checkbox" data-compare="${c.id}" ${S.compare.includes(c.id)?'checked':''} aria-label="Compare ${c.id}"></td><td><button class="candidate-name" data-candidate="${c.id}"><span class="rank-no">${String(c.rank).padStart(2,'0')}</span><span><strong>Forge-${c.id.slice(0,6)}</strong><small>${c.genes?.residual?'RES':'CNN'} · D${c.genes?.depth||'—'} / C${c.genes?.channels||'—'}</small></span></button></td><td class="score">${c.score.toFixed(3)}</td><td class="mono">${compact(c.proxy.params)}</td><td class="mono">${compact(c.proxy.macs)}</td><td class="mono">${fmt(c.disagreement)}</td><td>${c.pareto?'<span class="badge green">Pareto</span>':''}</td></tr>`).join('')}</tbody></table>`;}
function candidateDetail(c,j){return `<div class="panel"><div class="panel-header"><h2>Selected · Forge-${c.id.slice(0,6)}</h2><div class="actions"><button class="btn small" data-action="open-candidate">${icon('graph')}Open on canvas</button><a class="btn small" href="/api/export/job/${j.id}">${icon('download')}Experiment record</a></div></div><div class="panel-body"><div class="stat-inline">${['synflow','snip','naswot'].map(n=>`<div><small>${n.toUpperCase()}</small><strong style="font-size:17px">${c.proxy.scores[n]==null?'N/A':Number(c.proxy.scores[n]).toExponential(3)}</strong><small>percentile ${fmt(c.proxy_ranks[n],3)}</small></div>`).join('')}<div><small>COMPUTE TIME</small><strong style="font-size:17px">${fmt(c.proxy.seconds,3)}s</strong><small>CPU · seed ${c.proxy.seed}</small></div></div><p class="field-note">NASWOT  is N/A when ReLU is missing or the activation kernel is singular. Disagreement is the range of proxy percentile ranks, not calibrated uncertainty.</p></div></div>`;}
function bindCandidateEvents(cs){$$('[data-candidate]').forEach(b=>b.onclick=()=>{S.candidate=b.dataset.candidate;render()});$$('[data-compare]').forEach(b=>b.onchange=()=>{S.compare=b.checked?[...new Set([...S.compare,b.dataset.compare])]:S.compare.filter(x=>x!==b.dataset.compare)});}
function jobProgress(j){return `<div class="run-status ${j.status}"><span class="status-dot"></span><span class="mono">${esc(j.kind.toUpperCase())} / ${j.id.slice(0,8)}</span><span style="margin-left:auto">${badge(j.status)}</span></div><div class="progress"><span style="width:${j.progress*100}%"></span></div><div class="run-details"><span>${pct(j.progress)} complete</span><span>${j.seconds?fmt(j.seconds,2)+' CPU-s elapsed':''}${j.device?'device: '+esc(j.device):''}</span></div>${j.error?`<div class="error-box">${esc(j.error)}</div>`:''}<div class="actions" style="margin-top:12px;margin-bottom:8px">${['running','queued'].includes(j.status)?`${j.kind==='train'?`<button class="btn small" data-control="pause" data-id="${j.id}">${icon('pause')}Pause</button>`:''}<button class="btn small danger" data-control="cancel" data-id="${j.id}">${icon('stop')}Cancel</button>`:''}${['paused','interrupted','failed'].includes(j.status)&&j.kind==='train'?`<button class="btn small primary" data-control="resume" data-id="${j.id}">${icon('play')}Resume from checkpoint</button>`:''}<a class="btn small output-link" href="/api/export/job/${j.id}">${icon('download')}Export records${j.checkpoint?' and weights':''}</a></div>`;}
async function startTask(kind,options={}){const did=S.project.dataset_id||dataset()?.id;if(!did)throw Error('Select a dataset first');const j=await api('/jobs/'+kind,'POST',{project_id:S.project.id,dataset_id:did,ir:S.ir,...options});S.jobs.unshift(j);toast(kind==='train'?'Training queued locally':'Compute task queued locally');return j;}

function renderTraining(){const j=currentTrain(),ms=j?.metrics||[],last=ms.at(-1);$('#page').innerHTML=heading('TRAIN / 04','Training Studio','From a short validation run to reproducible training.',btn('Create training task','configure-train','play',true))+`<div class="metrics-strip">${metric('VALIDATION ACCURACY',j?pct(j.best_val_accuracy):'—','','Best validation accuracy','activity')}${metric('TRAINING LOSS',last?fmt(last.train_loss,4):'—','','Last completed epoch','layers')}${metric('THROUGHPUT',last?fmt(last.samples_per_second,1):'—','img/s','Training samples / full epoch time (including validation)','activity')}${metric('HELD-OUT TEST',j?pct(j.test_accuracy):'—','','Evaluates best validation weights after training','check')}</div><div class="page-content"><div class="split-layout"><div class="stack"><div class="panel"><div class="panel-header"><h2>Active Experiment</h2>${j?badge(j.status):'<span class="muted">Not started</span>'}</div><div class="panel-body">${j?jobProgress(j):empty('Start your first training run','Train the current graph or choose a candidate in Search Lab. Curves come from real forward and backward passes.',btn('Configure training','configure-train','play',true))}</div></div><div class="two-charts"><div class="panel"><div class="panel-header"><h2>Loss</h2><small>lower is better</small></div><div class="panel-body">${lineChart(ms,['train_loss','val_loss'],['Train','Validation'])}</div></div><div class="panel"><div class="panel-header"><h2>Accuracy</h2><small>training / validation</small></div><div class="panel-body">${lineChart(ms,['train_accuracy','val_accuracy'],['Train','Validation'],true)}</div></div></div><div class="panel"><div class="panel-header"><h2>Runtime Console</h2><small>local worker logs</small></div><div class="panel-body job-log">${j?.logs?.map(l=>`<div><span class="muted">${clockTime(l.time)}</span> ${esc(l.text)}</div>`).join('')||'Waiting for training…'}</div></div></div><aside class="stack"><div class="panel"><div class="panel-header"><h2>Training Configuration</h2>${icon('settings')}</div><div class="panel-body">${j?trainingConfig(j):`<p class="field-note">Optimizer: AdamW<br>Scheduler: CosineAnnealingLR<br>FP32 · Gradient clipping: 5<br>Single-machine CPU / CUDA · Fixed seed</p>`}<div class="info-box">Atomic checkpoints at epoch boundaries. Pause takes effect after an epoch; resume restores model, optimizer, scheduler and RNG.</div>${btn('Configure experiment','configure-train','plus')}</div></div><div class="panel"><div class="panel-header"><h2>Run History</h2><small>${projectJobs('train').length}</small></div>${projectJobs('train').length?projectJobs('train').slice(0,10).map(x=>`<button class="job-card full-width ${x.id===j?.id?'active':''}" data-train-job="${x.id}"><div><strong>${x.payload.source_candidate?'Forge-'+x.payload.source_candidate.slice(0,6):'Manual design'}</strong><small>${clockTime(x.created_at)} · ${x.metrics.length}/${x.payload.epochs} epochs</small></div>${badge(x.status)}</button>`).join(''):empty('No experiments yet','Results will appear here after creating a training run.')}</div></aside></div></div>`;$$('[data-train-job]').forEach(b=>b.onclick=()=>{S.trainJob=b.dataset.trainJob;render()});}
function trainingConfig(j){const p=j.payload;return [['Optimizer','AdamW'],['Scheduler','CosineAnnealingLR'],['Learning rate',p.lr],['Weight decay',p.weight_decay],['Batch size',p.batch_size],['Epochs',p.epochs],['Seed',p.seed],['Device',j.device||p.device],['Dataset',p.dataset_id.slice(0,12)],['Candidate',p.source_candidate||'manual']].map(([k,v])=>`<div class="inspector-kv"><span>${k}</span><code>${esc(v)}</code></div>`).join('');}
function lineChart(ms,keys,names,percent=false){const w=400,h=230,l=42,r=14,t=18,b=38;const vals=ms.flatMap(m=>keys.map(k=>m[k]));const max=percent?1:Math.max(.01,...vals)*1.12;const count=Math.max(2,...ms.map(m=>m.epoch));const x=m=>l+(m.epoch-1)/(count-1)*(w-l-r),y=v=>t+(1-v/max)*(h-t-b);return `<svg class="chart" viewBox="0 0 ${w} ${h}" aria-label="${names.join(' and ')} chart">${[0,.25,.5,.75,1].map(v=>`<line class="gridline" x1="${l}" x2="${w-r}" y1="${y(v*max)}" y2="${y(v*max)}"/><text text-anchor="end" x="${l-8}" y="${y(v*max)+3}">${percent?Math.round(v*100)+'%':(v*max).toFixed(2)}</text>`).join('')}<text x="${w/2}" y="${h-7}" text-anchor="middle">EPOCH →</text>${ms.filter((_,i)=>i%Math.max(1,Math.ceil(ms.length/7))===0).map(m=>`<text x="${x(m)}" y="${h-b+17}" text-anchor="middle">${m.epoch}</text>`).join('')}${keys.map((k,i)=>`<polyline fill="none" stroke="${i?'var(--blue)':'var(--accent)'}" stroke-width="2" points="${ms.map(m=>`${x(m)},${y(m[k])}`).join(' ')}"/>${ms.map(m=>`<circle cx="${x(m)}" cy="${y(m[k])}" r="2.5" fill="${i?'var(--blue)':'var(--accent)'}"><title>Epoch ${m.epoch} · ${names[i]} ${m[k].toFixed(4)}</title></circle>`).join('')}`).join('')}${!ms.length?`<text x="${w/2}" y="${h/2}" text-anchor="middle">Waiting for the first epoch…</text>`:''}</svg><div class="legend">${names.map((n,i)=>`<span><b style="background:${i?'var(--blue)':'var(--accent)'}"></b>${n}</span>`).join('')}</div>`;}
function configureTrain(candidate=null,sourceJob=null){const d=S.datasets.find(x=>x.id===S.project.dataset_id)||dataset();modal(candidate?'Train candidate · Forge-'+candidate.id.slice(0,6):'Train current network',`<p>${candidate?'Uses the selected candidate architecture snapshot.':'Uses the current canvas architecture snapshot.'} Dataset version: <strong class="accent">${esc(d?.name||'Not selected')}</strong>. All configuration and model details are saved with the experiment.</p><form id="train-form"><div class="form-grid">${field('Epochs','epochs',5,'number','min="1" max="200"')}${field('Batch size','batch_size',32,'number','min="2" max="128"')}${field('Learning rate','lr',.001,'number','min="0.000001" max="0.1" step="any"')}${field('Weight decay','weight_decay',.0001,'number','min="0" max="1" step="0.0001"')}${field('Random seed','seed',42,'number','min="0"')}<label class="field"><span>Compute device</span><select name="device"><option value="cpu">CPU · Local</option><option value="cuda" ${!S.system.cuda?'disabled':''}>CUDA GPU ${S.system.cuda?'':'· Not detected'}</option></select></label></div><div class="info-box">AdamW + CosineAnnealingLR · FP32 · Gradient clipping at 5 · Epoch checkpoints. This task uses local compute resources.</div><button type="submit" class="btn primary full-width">${icon('play')}Confirm & start training</button></form>`);$('#train-form').onsubmit=fire(async e=>{e.preventDefault();const f=new FormData(e.currentTarget),p={};for(const [k,v] of f)p[k]=k==='device'?v:Number(v);if(candidate){p.ir=candidate.ir;p.source_candidate=candidate.id;p.source_job=sourceJob.id;p.dataset_id=sourceJob.payload.dataset_id;}const j=await startTask('train',p);S.trainJob=j.id;$('#modal').close();navigate('training')});}

function renderExperiments(){const js=projectJobs().filter(j=>j.payload?.ir);$('#page').innerHTML=heading('REPRODUCE / 05','Experiment Lab','Every exploration leaves a trace.',btn('Compare training results','compare-runs','compare')+btn('Refresh records','refresh','activity'))+`<div class="page-content"><div class="panel"><div class="panel-header"><h2>All Experiments <small>${js.length} runs</small></h2><span class="badge green">SAVED TO WORKSPACE</span></div><div class="table-scroll">${js.length?`<table><thead><tr><th></th><th>Experiment</th><th>Status</th><th>Dataset version</th><th>Params</th><th>Best val</th><th>Test</th><th>Created</th><th>Artifacts</th></tr></thead><tbody>${js.map(j=>`<tr><td>${j.kind==='train'?`<input type="checkbox" data-compare-run="${j.id}" aria-label="Compare experiment ${j.id}">`:''}</td><td><button class="candidate-name" data-open-job="${j.id}">${icon(j.kind==='train'?'activity':'orbit')}<span><strong>${({train:'Training',proxy:'Proxy analysis',profile:'Performance profile',debug:'Tensor capture',optimize:'Model optimization'})[j.kind]||j.payload.strategy+' Search'}</strong><small>${j.id.slice(0,12)}</small></span></button></td><td>${badge(j.status)}</td><td class="mono">${j.payload.dataset_id.slice(0,10)}</td><td class="mono">${compact(j.candidates[0]?.proxy.params||paramCount(j.payload.ir))}</td><td class="mono accent">${pct(j.best_val_accuracy)}</td><td class="mono">${pct(j.test_accuracy)}</td><td class="mono muted">${new Date(j.created_at*1000).toLocaleDateString()} ${clockTime(j.created_at)}</td><td><a class="btn small" href="/api/export/job/${j.id}">${icon('download')}Export</a></td></tr>`).join('')}</tbody></table>`:empty('No experiment records yet','Run a proxy analysis, search or training task to track its results here.')}</div></div><div class="capabilities section-gap"><div class="capability"><h3>Architecture & Dataset Lineage</h3><p>Each task saves its architecture, dataset version, split indices, seed, configuration and code version. Saving a project preserves architecture history.</p><button class="link-button section-gap" data-action="versions">View current architecture versions →</button></div><div class="capability"><h3>Reproducible Artifacts</h3><p>Export model code, IR, experiment records, pipeline manifest and available local weights. Dataset images stay in runtime/datasets.</p><button class="link-button section-gap" data-action="export-project">Export current project →</button></div></div></div>`;$$('[data-open-job]').forEach(b=>b.onclick=()=>{const j=S.jobs.find(x=>x.id===b.dataset.openJob);if(j.kind==='train'){S.trainJob=j.id;navigate('training')}else if(['debug','profile'].includes(j.kind)){S.inspectionJob=j.id;navigate('inspect')}else if(j.kind==='optimize'){S.optimizationJob=j.id;navigate('optimization')}else{S.searchJob=j.id;navigate('search')}});}
function paramCount(ir){if(JSON.stringify(ir)===JSON.stringify(S.ir))return S.analysis?.params;return null;}
function renderSettings(){$('#page').innerHTML=heading('SYSTEM / 06','Runtime & capabilities','Understand the current implementation and compute environment.')+`<div class="page-content"><div class="panel"><div class="panel-header"><h2>Local Runtime</h2><span class="badge green">CONNECTED</span></div><div class="panel-body"><pre class="settings-code">${esc(JSON.stringify(S.system,null,2))}</pre></div></div><div class="capabilities section-gap">${[['Architecture IR & Compiler','Implemented','CNN、ResidualBlock、Add、Concat  operators. Graph-to-PyTorch compilation, shape checks and resource budgets.'],['Dataset & Versioning','Implemented','Image classification ZIPs, quality checks, content hashes, duplicate grouping, stratified splits and version manifests.'],['Zero-Cost Proxy','Implemented','Params、MACs、SynFlow、SNIP、NASWOT, Real CPU computation. No calibrated accuracy predictions.'],['Architecture Search','Implemented','Template random and evolutionary search, hard constraints, duplicate filtering, percentile ranking and score-size Pareto frontier.'],['Training & Recovery','Implemented','Single-machine CPU / CUDA, AdamW, cosine scheduler, gradient clipping, checkpoints, pause / resume and held-out evaluation.'],['Research Extensions','Planned','ViT / LLM / MoE、Code → Visual、AI Copilot、Meta-Proxy  calibration, distributed training and multi-tenancy.']].map(([title,status,text])=>`<div class="capability"><h3>${title} <span class="badge ${status==='Implemented'?'green':'orange'}">${status}</span></h3><p>${text}</p></div>`).join('')}</div><div class="info-box warning">Local single-user engineering workspace. Synthetic Shapes verifies the software workflow. Proxy ranking is not calibrated accuracy; runtime measurements are recorded by actual compute jobs.</div><p class="field-note">Implementation references: <a target="_blank" rel="noreferrer" href="https://docs.pytorch.org/tutorials/beginner/saving_loading_models.html">PyTorch · Saving & Loading Models</a> · <a target="_blank" rel="noreferrer" href="https://github.com/mohsaied/zero-cost-nas">Zero-Cost NAS</a> · <a target="_blank" rel="noreferrer" href="https://github.com/BayesWatch/nas-without-training">NASWOT</a></p></div>`;}

async function showProjects(){S.projects=await api('/projects');modal('Your projects',S.projects.map(p=>`<button class="project-row" data-project="${p.id}"><strong>${esc(p.name)}</strong><span>v${p.revision} · ${p.id.slice(0,8)}</span></button>`).join('')+`<form id="new-project" class="section-gap"><label class="field"><span>New project name</span><input name="name" required maxlength="120" placeholder="Example: Edge Vision / Experiment 02"></label><button class="btn primary" type="submit">${icon('plus')}Create project</button></form>`);$$('[data-project]').forEach(b=>b.onclick=fire(async()=>{if(S.dirty){const result=await analyze(false);if(!result)throw Error('Fix graph validation errors or export the draft before switching projects');await save()}$('#modal').close();await loadProject(S.projects.find(p=>p.id===b.dataset.project))}));$('#new-project').onsubmit=fire(async e=>{e.preventDefault();if(S.dirty)await save();const p=await api('/projects','POST',{name:new FormData(e.currentTarget).get('name'),dataset_id:dataset().id});S.projects.unshift(p);$('#modal').close();await loadProject(p)});}
async function uploadModal(){modal('Import image classification dataset',`<form id="upload-form"><label class="upload-area" style="display:block">${icon('upload')}<h3>Choose image ZIP</h3><p>class_name/image.png · Compressed archive up to 100 MB<br>2–100  classes · At least 3 independent images per class</p><input type="file" name="file" accept=".zip" required></label><div class="form-grid section-gap"><label class="field"><span>Image size</span><select name="size"><option>16</option><option selected>32</option><option>64</option><option>128</option></select></label>${field('Split seed','seed',42,'number','min="0"')}</div><div class="info-box">Creates a new data version and preserves originals. Default train / validation / test split is approximately 70% / 15% / 15%; small classes round by independent image group.</div><button class="btn primary full-width" type="submit">${icon('upload')}Import, inspect & version</button></form>`);$('#upload-form').onsubmit=fire(async e=>{e.preventDefault();const button=$('button[type="submit"]',e.currentTarget);button.disabled=true;button.textContent='Decoding and analyzing…';try{const d=await api('/datasets','POST',new FormData(e.currentTarget));S.datasets=await api('/datasets');S.dataset=d.id;$('#modal').close();toast('Dataset imported. Apply it to the current model.');navigate('datasets')}finally{button.disabled=false;button.textContent='Import, inspect & version'}});}
async function applyDataset(){const d=dataset();history();S.ir.input_shape=d.shape;const out=S.ir.nodes.find(n=>n.id===S.ir.output);if(out?.op==='Linear')out.config.out_features=d.classes.length;S.project.dataset_id=d.id;setDirty();await analyze(false);await save();toast('Dataset applied; input and classifier updated');render();}
function compareCandidates(){const cs=currentSearch()?.candidates||[];let selected=cs.filter(c=>S.compare.includes(c.id));if(selected.length===0)selected=cs.slice(0,2);if(selected.length!==2)throw Error('Select exactly two candidates to compare');const [a,b]=selected;modal('Architecture Diff',`<div class="compare-grid">${[a,b].map((c,i)=>{const other=i?a:b;return `<div><h3>Forge-${c.id.slice(0,6)}</h3><p>${compact(c.proxy.params)} parameters · score ${c.score.toFixed(3)}</p>${c.ir.nodes.map((n,idx)=>{const match=other.ir.nodes[idx],different=JSON.stringify(n)!==JSON.stringify(match);return `<div class="diff-row ${different?'changed':''}"><strong>${esc(n.op)}</strong> <span class="muted">${esc(n.id)}</span><br>${esc(JSON.stringify(n.config))}<br><span class="muted">← ${esc(n.inputs.join(', '))}</span></div>`}).join('')}</div>`}).join('')}</div><p>Yellow indicates different nodes, parameters or connections at the same index.</p>`);}
function compareRuns(){const ids=$$('[data-compare-run]:checked').map(x=>x.dataset.compareRun);if(ids.length<2||ids.length>4)throw Error('Select 2–4  training experiments');const js=ids.map(id=>S.jobs.find(j=>j.id===id));modal('Training comparison',`<div class="table-scroll"><table><thead><tr><th>Metric</th>${js.map(j=>`<th>${j.id.slice(0,8)}</th>`).join('')}</tr></thead><tbody>${[['Status',j=>j.status],['Dataset',j=>j.payload.dataset_id.slice(0,10)],['Candidate',j=>j.payload.source_candidate||'manual'],['Seed',j=>j.payload.seed],['Epochs',j=>j.metrics.length+'/'+j.payload.epochs],['Best validation',j=>pct(j.best_val_accuracy)],['Held-out test',j=>pct(j.test_accuracy)],['Epoch seconds',j=>fmt(j.metrics.reduce((s,m)=>s+m.seconds,0),2)],['Learning rate',j=>j.payload.lr],['Batch size',j=>j.payload.batch_size]].map(([k,fn])=>`<tr><td>${k}</td>${js.map(j=>`<td class="mono">${esc(fn(j))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="info-box warning">Compare results only with the same data version, split and evaluation protocol. Short training is not full training.</div>`);}
async function versions(){const vs=await api('/projects/'+S.project.id+'/versions');modal('Architecture versions',vs.length?vs.map(v=>`<button class="project-row" data-version="${v.id}"><strong>Revision ${v.revision}</strong><span>${v.ir.nodes.length} operators · ${clockTime(v.created_at)} · Restore to canvas</span></button>`).join(''):'<p>Each project save preserves the preceding version.</p>');$$('[data-version]').forEach(b=>b.onclick=fire(async()=>{const v=vs.find(v=>v.id===b.dataset.version);history();S.ir=clone(v.ir);S.project.dataset_id=v.dataset_id;S.dataset=v.dataset_id;S.positions=clone(v.layout||{});setDirty();await analyze(false);$('#modal').close();navigate('architecture')}));}
function download(text,name,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function templateModal(){modal('Create network template',`<form id="template-form"><div class="form-grid"><label class="field"><span>Block family</span><select name="residual"><option value="true">Residual Block</option><option value="false">Conv2d + ReLU</option></select></label>${field('Block depth','depth',2,'number','min="1" max="4"')}${field('Base channels','channels',16,'number','min="4" max="64" step="4"')}${field('Network name','name','ForgeNet','text','maxlength="80"')}</div><p>Replaces the current draft. Undo restores the previous graph.</p><button type="submit" class="btn primary">${icon('graph')}Generate editable network</button></form>`);$('#template-form').onsubmit=fire(async e=>{e.preventDefault();const f=new FormData(e.currentTarget),d=dataset();history();S.ir=makeTemplate(Number(f.get('channels')),Number(f.get('depth')),f.get('residual')==='true',d.classes.length,d.shape[1]);S.ir.name=f.get('name');S.selected=S.ir.nodes[0].id;S.positions={};setDirty();await analyze(false);$('#modal').close();navigate('architecture')});}
function makeTemplate(channels,depth,residual,classes,size){let nodes=[],prev='input';for(let i=0;i<depth;i++){let id='block'+(i+1);nodes.push({id,op:residual?'ResidualBlock':'Conv2d',inputs:[prev],config:{out_channels:channels*Math.min(2**i,4),kernel_size:3,stride:1,padding:1}});if(!residual){nodes.push({id:'act'+(i+1),op:'ReLU',inputs:[id],config:{}});id='act'+(i+1)}nodes.push({id:'pool'+(i+1),op:'MaxPool2d',inputs:[id],config:{kernel_size:2}});prev='pool'+(i+1)}nodes.push({id:'gap',op:'AdaptiveAvgPool2d',inputs:[prev],config:{}},{id:'flatten',op:'Flatten',inputs:['gap'],config:{}},{id:'classifier',op:'Linear',inputs:['flatten'],config:{out_features:classes}});return {schema_version:1,name:'ForgeNet',input_shape:[3,size,size],nodes,output:'classifier'}}
const ACTIONS={
 save, 'validate':async()=>{await analyze();render()},'export-project':async()=>{if(S.dirty)await save();location.href='/api/export/project/'+S.project.id},
 'proxy':async()=>{const j=await startTask('proxy');S.consoleTab='proxy';render();log('Proxy analysis queued: '+j.id)},
 'graph-view':()=>{S.view='graph';render()},'code-view':()=>{S.view='code';render()},
 'download-code':async()=>{const r=await api('/code','POST',{ir:S.ir});download(r.code,'model.py')},
 'undo':async()=>{if(!S.history.length)return;S.future.push(clone(S.ir));S.ir=S.history.pop();S.positions={};setDirty();await analyze(false);render()},
 'redo':async()=>{if(!S.future.length)return;S.history.push(clone(S.ir));S.ir=S.future.pop();S.positions={};setDirty();await analyze(false);render()},
 'delete-node':deleteNode,'set-output':async()=>{history();S.ir.output=S.selected;setDirty();await analyze(false);render()},
 'zoom-in':()=>{S.zoom=Math.min(1.5,S.zoom*1.2);applyTransform()},'zoom-out':()=>{S.zoom=Math.max(.2,S.zoom/1.2);applyTransform()},
 'layout':()=>{S.positions={};layoutMissing();renderGraph()},'fit':()=>{const c=$('#canvas'),ps=Object.values(S.positions),mx=Math.max(...ps.map(p=>p.x))+200,my=Math.max(...ps.map(p=>p.y))+115;S.zoom=Math.min(1,(c.clientWidth-45)/mx,(c.clientHeight-60)/my);S.pan={x:20,y:28};applyTransform()},
 'template':templateModal,'import-ir':()=>{modal('Import Neural Architecture IR',`<p>Accepts JSON IR without executing Python. The compiler validates IR v1 nodes, edges and parameters.</p><form id="ir-form"><textarea name="ir" required spellcheck="false" aria-label="Architecture JSON">${esc(JSON.stringify(S.ir,null,2))}</textarea><button type="submit" class="btn primary section-gap">Validate & load</button></form>`);$('#ir-form').onsubmit=fire(async e=>{e.preventDefault();const ir=JSON.parse(new FormData(e.currentTarget).get('ir'));await api('/analyze','POST',{ir});history();S.ir=ir;S.space={schema_version:1,variables:[],nodes:{},global_constraints:{},local_constraints:[]};S.modulePath=[];S.positions={};setDirty();await analyze(false);$('#modal').close();render()})},
 'upload-dataset':uploadModal,'apply-dataset':applyDataset,'quality-report':()=>modal('Data quality & version manifest',`<pre class="settings-code">${esc(JSON.stringify(dataset(),null,2))}</pre>`),
 'resplit':()=>{const d=dataset();modal('Create a new split version',`<form id="split-form"><div class="form-grid">${field('Validation ratio','val',.15,'number','min="0.05" max="0.4" step="0.05"')}${field('Test ratio','test',.15,'number','min="0.05" max="0.4" step="0.05"')}${field('Random seed','seed',43,'number','min="0"')}</div><div class="info-box">Preserves the original version and creates a stratified split. Identical image content stays in one group.</div><button class="btn primary" type="submit">Create version</button></form>`);$('#split-form').onsubmit=fire(async e=>{e.preventDefault();const p=Object.fromEntries([...new FormData(e.currentTarget)].map(([k,v])=>[k,Number(v)]));const r=await api('/datasets/'+d.id+'/split','POST',p);S.datasets=await api('/datasets');S.dataset=r.id;$('#modal').close();render();toast('New dataset version created')})},
 'compare-candidates':compareCandidates,'open-candidate':async()=>{const j=currentSearch(),c=j?.candidates.find(c=>c.id===S.candidate)||j?.candidates[0];if(!c)throw Error('Complete an architecture search first');history();S.ir=clone(c.ir);S.project.dataset_id=j.payload.dataset_id;S.dataset=j.payload.dataset_id;S.positions={};S.selected=S.ir.nodes[0].id;setDirty();await analyze(false);navigate('architecture')},
 'train-candidate':()=>{const j=currentSearch(),c=j?.candidates.find(c=>c.id===S.candidate)||j?.candidates[0];if(!c)throw Error('Complete a search and select a candidate first');configureTrain(c,j)},'configure-train':()=>configureTrain(),
 'compare-runs':compareRuns,'versions':versions,'refresh':async()=>{S.jobs=await api('/jobs');render();toast('Experiment records refreshed')}
};
function bindAction(b){b.onclick=fire(async()=>{const f=ACTIONS[b.dataset.action];if(f)await f()});}
function bindActions(){$$('[data-action]').forEach(bindAction);$$('[data-control]').forEach(b=>b.onclick=fire(async()=>{await api('/jobs/'+b.dataset.id+'/control','POST',{action:b.dataset.control});S.jobs=await api('/jobs');render();toast(b.dataset.control==='pause'?'Pauses after the current epoch and checkpoint':'Task status updated')}));}
async function poll(){try{const old=new Map(S.jobs.map(j=>[j.id,j.status]));const jobs=await api('/jobs');const changed=JSON.stringify(jobs)!==JSON.stringify(S.jobs);S.jobs=jobs;for(const j of jobs){if(old.has(j.id)&&old.get(j.id)!==j.status){if(j.status==='completed')toast(`${j.kind==='train'?'Training':'Analysis'}Completed · ${j.id.slice(0,8)}`);if(j.status==='failed')toast('Task failed: '+j.error,true)}}const active=jobs.filter(j=>['running','queued','pausing','cancelling'].includes(j.status));$('#engine-status').textContent=`PyTorch ${S.system.torch} · ${active.length?active.length+' active task(s)':'ready'}`;if(S.page==='architecture')renderConsole();else if(changed&&!['cad','copilot','operators'].includes(S.page)&&!$('#modal').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){const scroll=window.scrollY;render();window.scrollTo(0,scroll)}}catch(e){$('#engine-status').textContent='Engine disconnected · reconnecting…';}finally{setTimeout(poll,1500)}}
document.addEventListener('keydown',e=>{const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();fire(save)();return}if(editing||$('#modal').open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();fire(ACTIONS.undo)()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();fire(ACTIONS.redo)()}if(e.key==='Delete'&&S.page==='architecture')fire(deleteNode)();if(e.key==='Escape'&&S.connecting){S.connecting=null;renderGraph()}});
$$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#project-switch').onclick=fire(showProjects);$('#theme').onclick=()=>{document.body.classList.toggle('light');localStorage.setItem('nf-theme',document.body.classList.contains('light')?'light':'dark')};if(localStorage.getItem('nf-theme')==='light')document.body.classList.add('light');
$('#help').onclick=()=>modal('Getting started with NeuroForge AI',`<p><strong class="accent">01 · Design</strong><br>Drag nodes, add components and edit parameters in Architecture Studio. Connect output and input ports; Add / Concat accept multiple inputs. Validate and save the graph.</p><p><strong class="accent">02 · Data</strong><br>Use built-in Shapes-300 to verify the workflow, or upload a ZIP with class folders, then click“Apply to current model”. </p><p><strong class="accent">03 · Explore</strong><br>Search Lab  to configure a template search space and constraints. Run proxy analysis, inspect ranks and the Pareto frontier, then short-train several candidates.</p><p><strong class="accent">04 · Train & deliver</strong><br>Training Studio  to review training configuration. Export model code, weights, configuration and reproducibility records in Experiment Lab.</p><div class="info-box">Ctrl+S Save · Ctrl+Z Undo · Ctrl+Y Redo · Delete to remove nodes. Runtime & capabilities lists implemented features and future scope.</div>`);
window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue='';}});
async function init(){$('#page').innerHTML='<div class="loading"><span class="spinner" style="display:inline-block"></span> Initializing local workspace…</div>';hydrate();try{[S.system,S.projects,S.datasets,S.jobs]=await Promise.all([api('/system'),api('/projects'),api('/datasets'),api('/jobs')]);$('#hardware').textContent=`${S.system.cuda?'CUDA':'CPU'} / PYTORCH ${S.system.torch}`;await loadProject(S.projects.find(p=>p.id===localStorage.getItem('nf-project'))||S.projects[0]);setTimeout(()=>{if(S.page==='architecture'&&S.view==='graph')ACTIONS.fit()},100);poll()}catch(e){$('#page').innerHTML=`<div class="loading"><h2>Cannot connect to the local engine</h2><p>${esc(e.message)}</p><p>Run start.bat or python run.py, then refresh this page.</p></div>`;toast(e.message,true)}}
